  ('crested-butte-colorado', '12A', 'Crested Butte', 'United States', 'The last great Colorado ski town', 'live', 'verified', 'northernLights', 'The Colorado Rockies', '{"family","hiking","romance","ski"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'emerging', '{"key_facts":["Crested Butte = ''the last great Colorado ski town,'' end-of-the-road Victorian mining town at ~8,885 ft, surrounded by ~1.6 million acres of public land","Crested Butte Mountain Resort (Vail Resorts, Epic Pass) = birthplace of inbounds extreme skiing; ~37% expert terrain; Rambo ~55-degree pitch","~1,547 acres / 165 trails / 15 lifts / 2,787-ft vertical / 12,162-ft summit / 9,375-ft base at Mt. Crested Butte","Epic Pass (Vail Resorts) — alongside Vail, Beaver Creek, Breckenridge, Keystone","Colorado''s Wildflower Capital (1,500+ flowering species)","Crested Butte Wildflower Festival each July (2026 = 40th anniversary, ~10-19 Jul); peak bloom mid-Jul-early Aug","Gunnison Valley Health = area hospital (Level IV trauma, ~30 mi down-valley, clinics in Crested Butte/Mt. CB)"],"safety":{"emergency":"911 (police/fire/ambulance/rescue dispatch, nationwide)","hospital":"Gunnison Valley Health (Gunnison, 24/7 ER + Level IV trauma, ~30 mi down-valley; clinics in Crested Butte/Mt. CB); serious cases airlift to Denver Front Range trauma centres; backcountry via Crested Butte Search and Rescue / Gunnison County / 911","malaria":"none","yellow_fever":"not required","activity_note":"ALTITUDE (town ~8,885 ft, terrain 12,162 ft) — AMS risk, acclimatize/hydrate; EXTREME TERRAIN (Rambo ~55 deg — expert only, respect closures); AVALANCHE beyond ropes (check CAIC daily, guide + beacon/probe/shovel); tree wells + extreme cold/fast weather (valley among coldest in US); end-of-road remoteness (hospital ~30 mi); summer high-trail/14er/401-Trail lightning + exposure","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/usa","read":"2026-09-01T16:18:24Z","page_updated":"2026-08-18T10:29:04+01:00","source_country":"usa","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":{"peak":"High winter (Christmas/NY, MLK + Presidents'' wknds, Feb) ski; summer Crested Butte Wildflower Festival (mid-July) + Jul-Aug wildflower/biking","shoulder":"early season (late Nov-mid Dec), Jan weekdays, late Mar-early Apr (spring corn), September (aspen color)","green":"mid-Apr-late May + Oct-mid Nov (mud seasons; some services close — verify)","booking_lead":"Christmas/NY + Wildflower Festival + top homes/Scarp Ridge 6-12 mo; Presidents''/Feb 4-8 mo; summer non-festival 2-5 mo; shoulder 2-8 wk","off_season_specials":"spring-corn deals (late Mar-Apr); Sep aspen-color + singletrack; early-season pre-Christmas ski; Wildflower Festival + summer biking/hiking as shoulder engines","event_peaks":"Crested Butte Wildflower Festival (mid-July), Christmas/NY, MLK + Presidents'' wknds, winter/fat-bike events (verify), summer bike/trail events","fire_date":"FIRE ski mid-late Mar (ahead of Apr-Jun early-bird) + late Aug-early Sep (ahead of Sep-Nov fall wave); market Wildflower Festival + summer high-country by Jan-Feb (festival lodging sells early)"},"jewels":[{"name":"Drop into the extreme terrain (Rambo + the North Face)","status":"future","tier":"comfort","price_band":"~USD 130-239/day lift","timing":"ski ~late Nov-early Apr, snow-dependent; expert only","draw_rank":1,"hook":"the birthplace of inbounds extreme skiing — steep chutes, cliffs and Rambo''s ~55-degree pitch, some of the most serious lift-served terrain in North America","si":"ski","blurb":"the birthplace of inbounds extreme skiing — steep chutes, cliffs and Rambo''s ~55-degree pitch, some of the most serious lift-served terrain in North America","when":"ski ~late Nov-early Apr, snow-dependent; expert only","commission":"DMC/ski-op 10-20% (embedded-capable)","wells":["activities"],"wells_basis":"derived from name/blur